function TROP_MATPOW(A, m):
    result <- tropical identity (0 on diagonal, +inf off-diagonal)
    base   <- A
    e      <- m
    while e > 0:
        if e is odd:
            result <- TROP_MATMUL(result, base)
        base <- TROP_MATMUL(base, base)
        e <- floor(e / 2)
    return result

function TROP_MATMUL(A, B):
    for i, j:
        out[i][j] <- min over k of (A[i][k] + B[k][j])
    return out

function MIN_MEAN_CYCLE(A):  # n x n weight matrix, +inf = absent edge
    d[0][v] <- 0 for all v
    for k in 1..n:
        for v in 0..n-1:
            d[k][v] <- min over u of (d[k-1][u] + A[u][v])
    lambda <- +inf
    for v in 0..n-1:
        worst <- max over k in 0..n-1 of (d[n][v] - d[k][v]) / (n - k)
        lambda <- min(lambda, worst)
    return lambda
